<?php
Prihod\Schedule::register();
Prihod\Public_View::register();
$service = wp_insert_post( array( 'post_type' => 'prihod_service', 'post_title' => 'Sunday liturgy', 'post_status' => 'publish' ) );
$_POST = array( 'prihod_service_nonce' => wp_create_nonce( 'prihod_service_' . $service ), 'prihod_service' => array( 'kind' => 'regular', 'date' => '2026-01-01', 'weekdays' => array( '7' ), 'time' => '09:00', 'location_id' => (string) $location ), 'prihod_exceptions' => array( array( 'original' => '2026-10-11', 'action' => 'cancel' ), array( 'original' => '2026-10-18', 'action' => 'replace', 'date' => '2026-10-19', 'time' => '10:00', 'location_id' => (string) $location ) ) );
Prihod\Schedule_Admin::save( $service );
$_POST = array();
$events = Prihod\Schedule::query( new DateTimeImmutable( '2026-10-10 UTC' ), new DateTimeImmutable( '2026-10-27 UTC' ) );
prihod_assert( 3 === count( $events ) && $events[0]['cancelled'] && '2026-10-19' === $events[1]['start']->format( 'Y-m-d' ), 'Real storage expands recurrence and exceptions.' );
prihod_assert( 2 === count( Prihod\Schedule::query( new DateTimeImmutable( '2026-10-10 UTC' ), new DateTimeImmutable( '2026-10-27 UTC' ), 0, false ) ), 'Cancelled occurrences do not count as upcoming.' );
prihod_assert( WP_Block_Type_Registry::get_instance()->is_registered( 'prihod/schedule' ), 'Dynamic schedule Gutenberg block is registered.' );
$_GET['prihod_date'] = '2026-10-11';
prihod_assert( str_contains( do_shortcode( '[prihod_schedule view="month"]' ), 'Sunday liturgy' ), 'Schedule shortcode renders actual services.' );
prihod_assert( str_contains( do_shortcode( '[prihod_schedule view="month"]' ), 'class="prihod-month"' ), 'Month view renders a real calendar grid.' );
$_GET['prihod_view'] = 'week';
prihod_assert( ! str_contains( do_shortcode( '[prihod_schedule view="month"]' ), 'class="prihod-month"' ), 'Public view switch changes month to week.' );
prihod_assert( str_contains( do_shortcode( '[prihod_schedule]' ), 'class="prihod-week"' ), 'Week view groups services by actual day.' );
$_GET['prihod_view'] = 'list';
prihod_assert( ! str_contains( do_shortcode( '[prihod_schedule]' ), 'class="prihod-week"' ), 'List view provides a separate chronological layout.' );
unset( $_GET['prihod_view'] );
unset( $_GET['prihod_date'] );
update_option( 'prihod_modules', array( 'schedule' => false ) );
prihod_assert( '' === Prihod\Public_View::render( 'schedule' ) && get_post_meta( $service, '_prihod_service', true ), 'Disabling schedule hides output and retains data.' );
update_option( 'prihod_modules', array( 'schedule' => true ) );
wp_set_current_user( $editor_id );
prihod_assert( ! current_user_can( 'edit_post', $service ), 'Editor cannot edit services without capability.' );
wp_set_current_user( 1 );

$formatter = new ReflectionMethod( Prihod\Public_View::class, 'event_html' ); $formatter->setAccessible( true );
$overnight = $formatter->invoke( null, array( 'title' => 'Vigil', 'start' => new DateTimeImmutable( '2040-10-17 23:00', new DateTimeZone( 'Europe/Berlin' ) ), 'end' => new DateTimeImmutable( '2040-10-18 01:00', new DateTimeZone( 'Europe/Berlin' ) ), 'location_id' => 0, 'cancelled' => false, 'moved' => false, 'description' => '' ) );
prihod_assert( str_contains( $overnight, '18.10.2040 01:00' ), 'Compact overnight services retain the next-day end date.' );

$columns = apply_filters( 'manage_prihod_service_posts_columns', array( 'cb' => 'Checkbox', 'title' => 'Title', 'date' => 'Date' ) );
prihod_assert( isset( $columns['prihod_service_when'], $columns['prihod_service_place'], $columns['prihod_service_kind'], $columns['prihod_service_changes'] ) && __( 'Дата публикации', 'prihod' ) === $columns['date'] && 'Checkbox' === $columns['cb'], 'Native service list exposes schedule columns and distinguishes publication date.' );
$rule_before = get_post_meta( $service, '_prihod_service', true );
$regular_row = Prihod\Schedule_Admin::column_data( $service );
prihod_assert( sprintf( __( 'С %s, без конечной даты', 'prihod' ), '01.01.2026' ) === $regular_row['date'] && str_contains( $regular_row['kind'], __( 'Вс', 'prihod' ) ), 'Regular list rows show a recurrence period and weekdays, not one occurrence date.' );
prihod_assert( sprintf( __( 'Отменённых дат: %1$d. Переносов: %2$d.', 'prihod' ), 1, 1 ) === $regular_row['changes'] && $rule_before === get_post_meta( $service, '_prihod_service', true ), 'Recurring exceptions are counted without labelling the entire rule cancelled or changing data.' );
$list_id = wp_insert_post( array( 'post_type' => 'prihod_service', 'post_title' => 'List fixture', 'post_status' => 'draft' ) );
$list_rule = array( 'kind' => 'single', 'date' => '2040-10-17', 'time' => '12:00', 'location_id' => $location );
update_post_meta( $list_id, '_prihod_service', $list_rule );
$row = Prihod\Schedule_Admin::column_data( $list_id );
prihod_assert( '17.10.2040' === $row['date'] && '12:00' === $row['time'] && Prihod\Schedule::timezone( $location ) === $row['timezone'] && get_the_title( $location ) === $row['place'], 'Single service row uses the stored date, time, location and inherited timezone, even for drafts.' );
$list_rule['exceptions'] = array( '2040-10-17' => array( 'action' => 'replace', 'date' => '2040-10-18', 'time' => '14:00', 'location_id' => $location, 'timezone' => 'America/New_York' ) );
update_post_meta( $list_id, '_prihod_service', $list_rule );
$row = Prihod\Schedule_Admin::column_data( $list_id );
prihod_assert( '18.10.2040' === $row['date'] && '14:00' === $row['time'] && 'America/New_York' === $row['timezone'] && str_contains( $row['changes'], '17.10.2040' ), 'Moved single service rows use the native occurrence engine and retain the original date.' );
$list_rule['exceptions'] = array( '2040-10-17' => array( 'action' => 'cancel' ) );
update_post_meta( $list_id, '_prihod_service', $list_rule );
prihod_assert( __( 'Отменено', 'prihod' ) === Prihod\Schedule_Admin::column_data( $list_id )['changes'], 'Cancelled single dates are labelled without changing publication status.' );
$list_rule['kind'] = 'holiday'; $list_rule['exceptions'] = array();
update_post_meta( $list_id, '_prihod_service', $list_rule );
prihod_assert( __( 'Праздничная', 'prihod' ) === Prihod\Schedule_Admin::column_data( $list_id )['kind'], 'Holiday services retain their actual type.' );
update_post_meta( $list_id, '_prihod_service', array( 'date' => 'invalid' ) );
prihod_assert( __( 'Не настроено', 'prihod' ) === Prihod\Schedule_Admin::column_data( $list_id )['date'], 'Incomplete or invalid drafts do not display fabricated service dates.' );

$changed_rule = $rule_before;
$changed_rule['weekdays'] = array( 6, 7 );
$changed_rule['exceptions'] = array( '2026-10-17' => array( 'action' => 'cancel' ), '2026-10-18' => array( 'action' => 'replace', 'date' => '2026-10-19', 'time' => '10:00', 'location_id' => $location ) );
update_post_meta( $service, '_prihod_service', $changed_rule );
$zone = new DateTimeZone( Prihod\Profile::get()['timezone'] );
$changes = Prihod\Schedule::changes( new DateTimeImmutable( '2026-10-12', $zone ), new DateTimeImmutable( '2026-10-19', $zone ), $location );
prihod_assert( 2 === count( $changes ) && $changes[0]['cancelled'] && $changes[1]['moved'] && '2026-10-19' === $changes[1]['start']->format( 'Y-m-d' ), 'Changes include a cancellation and a transfer beyond the selected week.' );
$_GET = array( 'prihod_date' => '2026-10-18', 'prihod_view' => 'week', 'prihod_place' => $location );
$schedule_html = Prihod\Public_View::render( 'schedule' );
prihod_assert( str_contains( $schedule_html, 'prihod-changes-card' ) && str_contains( $schedule_html, '19.10.2026 10:00' ) && str_contains( $schedule_html, 'has-cancellations' ) && str_contains( $schedule_html, 'has-moves' ), 'Overview and mini calendar expose actual cancelled and transferred dates.' );
prihod_assert( 7 === preg_match_all( '/<a class="[^"]*\bis-selected-week\b/', $schedule_html ), 'Mini calendar marks the selected week without marking the rest of the month.' );
prihod_assert( $changed_rule === get_post_meta( $service, '_prihod_service', true ), 'Reading schedule summaries does not change stored rules.' );
$_GET = array( 'prihod_date' => ( new DateTimeImmutable( 'now', $zone ) )->format( 'Y-m-d' ) );
$today_html = Prihod\Public_View::render( 'schedule' );
prihod_assert( 1 === substr_count( $today_html, 'aria-current="date"' ), 'The mini calendar shows today in the selected month, including cross-month weeks.' );
update_post_meta( $service, '_prihod_service', $rule_before );
$_GET = array( 'prihod_date' => '2026-02-01' );
prihod_assert( str_contains( Prihod\Public_View::render( 'schedule' ), __( 'На выбранный период изменений не отмечено.', 'prihod' ) ), 'An unchanged period shows an honest empty changes state.' );
$_GET = array();
